#include <iostream>
#include <memory>

std::unique_ptr<int> make_reading(int value) {
    int* reading = new int(value); // TODO: return an owning smart pointer
    return std::unique_ptr<int>();
}

int main() {
    const std::unique_ptr<int> reading = make_reading(7);
    std::cout << *reading << "\n";
    return 0;
}
